'use strict';
// Lossless source transport only. The public GLB is generated byte-for-byte from
// its pinned gzip source so GitHub connector requests stay below 16 MiB.
const fs=require('node:fs/promises'),path=require('node:path'),crypto=require('node:crypto'),zlib=require('node:zlib');
const root=path.resolve(__dirname,'..'),manifest=require('../resources/character-source/sources.json');
const hash=data=>crypto.createHash('sha256').update(data).digest('hex');
async function main(){for(const entry of manifest.sources){const target=path.join(root,entry.target);let data;try{data=await fs.readFile(target)}catch(error){if(error.code!=='ENOENT')throw error;}if(data){if(data.length!==entry.bytes||hash(data)!==entry.sha256)throw Error('Existing character asset differs from approved version: '+entry.target);continue;}const compressed=await fs.readFile(path.join(root,entry.path));if(compressed.length!==entry.compressedBytes||hash(compressed)!==entry.compressedSha256)throw Error('Character source archive integrity failed');data=zlib.gunzipSync(compressed,{maxOutputLength:entry.bytes});if(data.length!==entry.bytes||hash(data)!==entry.sha256)throw Error('Reconstructed character integrity failed');await fs.mkdir(path.dirname(target),{recursive:true});await fs.writeFile(target+'.tmp',data);await fs.rename(target+'.tmp',target);console.log('Prepared verified character source: '+entry.target);}}
main().catch(error=>{console.error(error.message);process.exitCode=1});
